input.newString:
/** Mark a listing fulfilled. Only the owner may do this. */
export function fulfillListing(id: number): ListingRow | undefined {
  return setStatus(id, 'fulfilled');
}

/** Soft-delete a listing. Only the owner or an admin may do this. */
export function softDeleteListing(id: number): ListingRow | undefined {
  return setStatus(id, 'deleted');
}

function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = getListingById(id);
  if (!listing) {
    throw new Error(`Listing with id ${id} not found`);
  }

  // Status transition matrix
  if (listing.status === 'active') {
    // From 'active', can transition to 'fulfilled' or 'deleted'
    if (status !== 'fulfilled' && status !== 'deleted') {
      throw new Error(`Cannot transition from 'active' to '${status}' for listing ${id}`);
    }
  } else if (listing.status === 'fulfilled') {
    // From 'fulfilled', can only transition to 'deleted'
    if (status !== 'deleted') {
      throw new Error(`Cannot transition from 'fulfilled' to '${status}' for listing ${id}`);
    }
  } else {
    // From any other status ('deleted', 'expired'), all transitions are forbidden
    throw new Error(`Cannot transition from '${listing.status}' to '${status}' for listing ${id}`);
  }

  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

