describe('setStatus', () => {
  it('allows active to fulfilled transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const result = fulfillListing(listing.id);
    expect(result?.status).toBe('fulfilled');
  });

  it('allows active to deleted transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const result = softDeleteListing(listing.id);
    expect(result?.status).toBe('deleted');
  });

  it('allows fulfilled to deleted transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const fulfilled = fulfillListing(listing.id);
    expect(fulfilled?.status).toBe('fulfilled');
    const result = softDeleteListing(fulfilled.id);
    expect(result?.status).toBe('deleted');
  });

  it('forbids fulfilled to fulfilled transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const fulfilled = fulfillListing(listing.id);
    expect(fulfilled?.status).toBe('fulfilled');

    expect(() => fulfillListing(fulfilled.id)).toThrow(/cannot transition from 'fulfilled' to 'fulfilled'/);
  });

  it('forbids fulfilled to active transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const fulfilled = fulfillListing(listing.id);
    expect(fulfilled?.status).toBe('fulfilled');

    expect(() => setStatus(fulfilled.id, 'active')).toThrow(/cannot transition from 'fulfilled' to 'active'/);
  });

  it('forbids deleted to fulfilled transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const deleted = softDeleteListing(listing.id);
    expect(deleted?.status).toBe('deleted');

    expect(() => fulfillListing(deleted.id)).toThrow(/cannot transition from 'deleted' to 'fulfilled'/);
  });

  it('forbids deleted to deleted transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const deleted = softDeleteListing(listing.id);
    expect(deleted?.status).toBe('deleted');

    expect(() => softDeleteListing(deleted.id)).toThrow(/cannot transition from 'deleted' to 'deleted'/);
  });

  it('forbids deleted to active transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const deleted = softDeleteListing(listing.id);
    expect(deleted?.status).toBe('deleted');

    expect(() => setStatus(deleted.id, 'active')).toThrow(/cannot transition from 'deleted' to 'active'/);
  });

  it('forbids active to active transition', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(listing.status).toBe('active');

    expect(() => setStatus(listing.id, 'active')).toThrow(/cannot transition from 'active' to 'active'/);
  });

  it('forbids expired to any transition', () => {
    seedServer();
    const db = getDb();
    const past = Date.now() - 30 * 24 * 3600 * 1000 - 1000; // Past expiry time
